192	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
193	    @Override
194	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
195	        // Idempotent create: when the request carries an 'Idempotency-Key' already seen on a
196	        // previous successful create, return the originally created owner with 200 instead of
197	        // creating a duplicate.
198	        String idempotencyKey = currentIdempotencyKey();
199	        if (idempotencyKey != null) {
200	            Integer existingId = idempotentCreates.get(idempotencyKey);
201	            if (existingId != null) {
202	                Owner existing = this.clinicService.findOwnerById(existingId);
203	                if (existing != null) {
204	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
205	                }
206	            }
207	        }
208	        // Validate & normalize the optional email; reject the create when it is present but invalid.
209	        if (!normalizeEmail(ownerFieldsDto)) {
210	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
211	        }
212	        // Validate & normalize the optional postcode; reject the create when it is present but
213	        // not valid for the owner's city (see normalizePostcode).
214	        if (!normalizePostcode(ownerFieldsDto)) {
215	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
216	        }
217	        // Normalize the supplied address — the structured 'addressLine1'/'addressLine2' when
218	        // present, otherwise the flat 'address' — storing the normalized form (and the composed
219	        // 'address') back on the DTO so it is what gets persisted and compared. Reject the create
220	        // when no address is supplied in either form (see normalizeAddresses).
221	        if (!normalizeAddresses(ownerFieldsDto)) {
222	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
223	        }
224	        // Reject the create when the owner's city is already at capacity, i.e. it already
225	        // contains 50 or more owners (compared case-insensitively).
226	        int ownersInCity = countOwnersInCity(ownerFieldsDto.getCity());
227	        if (ownersInCity >= 50) {
228	            return new ResponseEntity<>(HttpStatus.CONFLICT);
229	        }
230	        // Normalize the telephone to E.164; reject the create when it cannot form a valid number.
231	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
232	        if (normalizedTelephone == null) {
233	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
234	        }
235	        ownerFieldsDto.setTelephone(normalizedTelephone);
236	        // Consolidated duplicate detection. All duplicate checks are now expressed through the
237	        // single derived identity key: the SHA-256 hex of
238	        // '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>' (see OwnerMapper#identityKey).
239	        // A create is rejected with 409 only when the new owner's identity key collides with an
240	        // existing (non-deleted) owner's. Because the telephone is part of the key, two owners with
241	        // the same last name and postcode but different telephones no longer collide — they are
242	        // created (and may be flagged as a soft match below), not rejected. The former separate
243	        // household-duplicate 409 keyed on the computed householdId no longer applies.
244	        Owner candidate = ownerMapper.toOwner(ownerFieldsDto);
245	        String identityKey = ownerMapper.identityKey(candidate);
246	        boolean identityInUse = this.clinicService.findAllOwners().stream()
247	            .filter(existing -> !existing.isDeleted())
248	            .anyMatch(existing -> identityKey.equals(ownerMapper.identityKey(existing)));
249	        if (identityInUse) {
250	            return new ResponseEntity<>(HttpStatus.CONFLICT);
251	        }
252	        // Determine the effective registration date — the value supplied on the request, or the
253	        // server's current date when none was supplied — and roll it forward to the next business
254	        // day: a Saturday or Sunday moves to the following Monday. Everything derived from the
255	        // registration date (membership-number year segment, per-day create-limit) uses this
256	        // adjusted date.
257	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
258	        if (registrationDate == null) {
259	            registrationDate = LocalDate.now();
260	        }
261	        // Reject a supplied registration date that lies in the future (later than the
262	        // server's current date): an owner cannot be registered ahead of time.
263	        else if (registrationDate.isAfter(LocalDate.now())) {
264	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
265	        }
266	        registrationDate = toBusinessDay(registrationDate);
267	        // Reject the create when the daily sign-up limit has been reached, i.e. 100 or more
268	        // owners have already been registered on this (adjusted) business day.
269	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
270	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
271	        }
272	        HttpHeaders headers = new HttpHeaders();
273	        Owner owner = candidate;
274	        owner.setRegistrationDate(registrationDate);
275	        // Assign the unified memberId as '<REGION><FY><HASH8><CHK>': the region derived from the
276	        // owner's postcode (falling back to the city, then 'UNKNOWN'), the two-digit fiscal year of
277	        // the registration date, the first 8 upper-case hex characters of the SHA-256 of the
278	        // normalized telephone concatenated with the last name, and a single Luhn check digit over
279	        // the digits of '<REGION><FY><HASH8>'.
280	        owner.setMemberId(memberId(owner));
281	        // Record how many existing owners already share this owner's first and last name
282	        // (compared case-insensitively) at the moment before this owner is created.
283	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
284	        // Flag a bulk sign-up when more than 80 owners have already been created today, i.e.
285	        // registered on this (adjusted) business day before this owner is created.
286	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > 80);
287	        // Flag that the owner's city is approaching its capacity limit: it already held between
288	        // 40 and 49 owners (inclusive) before this owner was created. The hard rejection at 50
289	        // owners is handled above, so reaching this point means the count is below 50.
290	        owner.setCapacityWarning(ownersInCity >= 40 && ownersInCity < 50);
291	        // Record the size of this owner's household after this create: the number of existing
292	        // owners sharing the same household (i.e. the same computed householdId) plus this owner.
293	        owner.setHouseholdSize(countHouseholdMembers(owner) + 1);
294	        // Cap this owner's membership level at one above the current maximum membership level among
295	        // their existing household members. When the owner has no existing household member no cap
296	        // applies (a null cap; see OwnerMapper#membershipLevel).
297	        owner.setMembershipLevelCap(membershipLevelCap(owner));
298	        // Flag a possible (soft) duplicate: this owner is not a hard identity duplicate (its
299	        // identity key is distinct), but it shares an existing owner's Soundex last name and
300	        // postcode. When such a match exists, record it as 'possibleDuplicate' with
301	        // 'possibleDuplicateOf' set to the matching owner's id; otherwise it is not a possible
302	        // duplicate. A declared household member (the request sets 'sharesHousehold') is an
303	        // acknowledged member, not a suspected duplicate, so it is never flagged.
304	        Owner softMatch = findPossibleDuplicate(owner);
305	        boolean declaredMember = softMatch != null && Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
306	        if (declaredMember) {
307	            owner.setPossibleDuplicate(false);
308	            owner.setPossibleDuplicateOf(null);
309	        }
310	        else {
311	            owner.setPossibleDuplicate(softMatch != null);
312	            owner.setPossibleDuplicateOf(softMatch == null ? null : softMatch.getId());
313	        }
314	        this.clinicService.saveOwner(owner);
315	        // Emit an audit line recording the new owner's id, memberId, registration date and
316	        // membership level.
317	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
318	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
319	            ownerMapper.membershipLevel(owner));
320	        // Emit the immutable structured OWNER_CREATED event carrying a monotonically increasing
321	        // sequence and the owner's current primary identifier (the memberId).
322	        OwnerCreatedEvent event = new OwnerCreatedEvent(AUDIT_SEQ.incrementAndGet(), owner.getId(),
323	            primaryIdentifier(owner), ownerMapper.membershipLevel(owner), "OWNER_CREATED");
324	        AUDIT.info(AUDIT_MAPPER.writeValueAsString(event));
325	        // Enqueue a welcome notification for the newly created owner, carrying its id and memberId.
326	        NOTIFY.info("welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
327	        // Remember this create against its idempotency key so a later repeat returns the same
328	        // owner instead of creating a duplicate.
329	        if (idempotencyKey != null) {
330	            idempotentCreates.put(idempotencyKey, owner.getId());
331	        }
332	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
333	        headers.setLocation(UriComponentsBuilder.newInstance()
334	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
335	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
336	    }
