338	    /**
339	     * The non-blank {@code Idempotency-Key} header of the current request, or {@code null} when
340	     * absent, blank, or there is no bound request.
341	     */
342	    private static String currentIdempotencyKey() {
343	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
344	        if (!(attributes instanceof org.springframework.web.context.request.ServletRequestAttributes servletAttributes)) {
345	            return null;
346	        }
347	        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
348	        return (key == null || key.isBlank()) ? null : key;
349	    }
