351	    /**
352	     * Validate and normalize the optional owner email in place.
353	     *
354	     * <p>An absent (or blank) email is allowed and is normalized to {@code null}.
355	     * When present it must be a syntactically valid address; a valid address is
356	     * stored back on the DTO lower-cased. Returns {@code false} when an email is
357	     * present but syntactically invalid, so the caller can reject with 400.
358	     */
359	    private boolean normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
360	        String email = ownerFieldsDto.getEmail();
361	        if (email == null || email.isBlank()) {
362	            ownerFieldsDto.setEmail(null);
363	            return true;
364	        }
365	        String normalized = email.trim().toLowerCase(Locale.ROOT);
366	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
367	            return false;
368	        }
369	        // Reject addresses whose domain is on the disposable-domain blocklist.
370	        String domain = normalized.substring(normalized.indexOf('@') + 1);
371	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
372	            return false;
373	        }
374	        ownerFieldsDto.setEmail(normalized);
375	        return true;
376	    }
377	
378	    /**
379	     * Validate the optional owner postcode in place.
380	     *
381	     * <p>An absent (or blank) postcode is allowed and is normalized to {@code null}.
382	     * When present it must be exactly 4 digits, and — when the owner's city maps to a
383	     * known region via {@link OwnerMapper#CITY_REGION} — it must fall within that
384	     * region's inclusive postcode range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
385	     * A city with no known region accepts any 4-digit postcode. Returns {@code false}
386	     * when a postcode is present but malformed or out of range, so the caller can
387	     * reject with 400.
388	     */
389	    private boolean normalizePostcode(OwnerFieldsDto ownerFieldsDto) {
390	        String postcode = ownerFieldsDto.getPostcode();
391	        if (postcode == null || postcode.isBlank()) {
392	            ownerFieldsDto.setPostcode(null);
393	            return true;
394	        }
395	        if (!postcode.matches("\\d{4}")) {
396	            return false;
397	        }
398	        String region = OwnerMapper.CITY_REGION.get(ownerFieldsDto.getCity());
399	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
400	        if (range != null) {
401	            int value = Integer.parseInt(postcode);
402	            if (value < range[0] || value > range[1]) {
403	                return false;
404	            }
405	        }
406	        return true;
407	    }
