325	        String email = owner.getEmail() == null ? "" : owner.getEmail();
326	        String key = telephone + "|" + email + "|" + Soundex.of(owner.getLastName());
327	        try {
328	            byte[] digest = MessageDigest.getInstance("SHA-256")
329	                .digest(key.getBytes(StandardCharsets.UTF_8));
330	            StringBuilder sb = new StringBuilder(digest.length * 2);
331	            for (byte b : digest) {
332	                sb.append(String.format("%02x", b));
333	            }
334	            return sb.toString();
335	        }
336	        catch (java.security.NoSuchAlgorithmException e) {
337	            throw new IllegalStateException(e);
338	        }
339	    }
340	
341	    private static String normalizeHouseholdKey(String value) {
342	        if (value == null) {
343	            return "";
344	        }
345	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
346	    }
