351	    @Mapping(target = "pets", ignore = true)
352	    Owner toOwner(OwnerFieldsDto ownerDto);
353	
354	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
355	
356	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
357	
358	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
359	        OwnerPageDto ownerPageDto = new OwnerPageDto();
360	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
361	        ownerPageDto.setPage(ownerPage.getNumber());
362	        ownerPageDto.setSize(ownerPage.getSize());
363	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
364	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
365	        return ownerPageDto;
366	    }
367	}
